using System;
using System.IO;
using System.Text;
class PatchCoreTests {
 static void Asar(string file,string name,string version){var package=Encoding.UTF8.GetBytes("{\"name\":\""+name+"\",\"version\":\""+version+"\"}");var header=Encoding.UTF8.GetBytes("{\"files\":{\"package.json\":{\"size\":"+package.Length+",\"offset\":\"0\"}}}");int body=4+header.Length;int padded=(body+3)/4*4;using(var stream=File.Create(file))using(var w=new BinaryWriter(stream)){w.Write(4);w.Write(4+padded);w.Write(padded);w.Write(header.Length);w.Write(header);for(int i=body;i<padded;i++)w.Write((byte)0);w.Write(package);}}
 static string Fixture(string root){var folder=Path.Combine(root,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(folder,"resources","codex-win32-x64","bin"));File.WriteAllText(Path.Combine(folder,"FantasyStory.exe"),"fixture");File.WriteAllText(Path.Combine(folder,"resources","codex-win32-x64","bin","codex.exe"),"keep-codex");Asar(Path.Combine(folder,"resources","app.asar"),"fantasy-story-desktop","0.1.0");File.WriteAllText(Path.Combine(folder,"saved-game.txt"),"keep-save");return folder;}
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static int Main(){var root=Path.Combine(Path.GetTempPath(),"fantasy-patch-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
  var payload=Path.Combine(root,"payload");Asar(payload,"fantasy-story-desktop","0.5.1");var m=new Manifest{product="FantasyStory",version="0.5.1",minimumVersion="0.1.0",sha256=PatchCore.Hash(payload)};
  var good=Fixture(root);var old=PatchCore.Hash(Path.Combine(good,"resources","app.asar"));var backup=PatchCore.Apply(good,payload,m);Check(PatchCore.Hash(Path.Combine(good,"resources","app.asar"))==m.sha256,"update failed");Check(PatchCore.Hash(backup)==old,"backup failed");Check(PatchCore.InstalledVersion(good)=="0.5.1","version failed");Check(File.ReadAllText(Path.Combine(good,"saved-game.txt"))=="keep-save","save changed");Check(File.ReadAllText(Path.Combine(good,"resources","codex-win32-x64","bin","codex.exe"))=="keep-codex","codex changed");
  var corrupt=Fixture(root);old=PatchCore.Hash(Path.Combine(corrupt,"resources","app.asar"));var bad=new Manifest{product=m.product,version=m.version,minimumVersion=m.minimumVersion,sha256=new String('0',64)};bool rejected=false;try{PatchCore.Apply(corrupt,payload,bad);}catch{rejected=true;}Check(rejected&&PatchCore.Hash(Path.Combine(corrupt,"resources","app.asar"))==old,"corrupt payload changed installation");
  var rollback=Fixture(root);old=PatchCore.Hash(Path.Combine(rollback,"resources","app.asar"));Directory.CreateDirectory(Path.Combine(rollback,"resources","desktop-version.json"));rejected=false;try{PatchCore.Apply(rollback,payload,m);}catch{rejected=true;}Check(rejected&&PatchCore.Hash(Path.Combine(rollback,"resources","app.asar"))==old,"rollback failed");
  var newer=Fixture(root);File.WriteAllText(Path.Combine(newer,"resources","desktop-version.json"),"{\"product\":\"FantasyStory\",\"version\":\"9.0.0\"}");rejected=false;try{PatchCore.Apply(newer,payload,m);}catch{rejected=true;}Check(rejected,"downgrade accepted");
  var legacy=Fixture(root);Directory.Delete(Path.Combine(legacy,"resources","codex-win32-x64"),true);Check(PatchCore.InspectionError(legacy)==null,"hardcoded CLI location rejected valid game");Check(PatchCore.InstalledVersion(legacy)=="0.1.0","ASAR version fallback failed");PatchCore.Apply(legacy,payload,m);
  Check(InstallationLocator.Resolve(Path.Combine(legacy,"FantasyStory.exe"))==legacy,"EXE selection failed");Check(InstallationLocator.Resolve(Path.Combine(legacy,"resources"))==legacy,"resources selection failed");
  var nested=Path.Combine(root,"unzip");Directory.CreateDirectory(nested);var single=Fixture(nested);Check(InstallationLocator.Resolve(nested)==single,"outer extraction folder failed");Fixture(nested);rejected=false;try{InstallationLocator.Resolve(nested);}catch{rejected=true;}Check(rejected,"ambiguous roots auto-selected");
  var other=Fixture(root);Asar(Path.Combine(other,"resources","app.asar"),"unrelated-app","0.1.0");rejected=false;try{PatchCore.Apply(other,payload,m);}catch{rejected=true;}Check(rejected,"other Electron app accepted");
  var broken=Fixture(root);File.WriteAllText(Path.Combine(broken,"resources","app.asar"),"bad");Check(PatchCore.InspectionError(broken)!=null,"broken ASAR accepted");
  var found=InstallationLocator.Find(new string[]{good,good,nested,other},2,300);Check(found.Count==3,"discovery did not deduplicate or rejected valid roots");
  Console.WriteLine("Patch tests passed: identity, ASAR version, custom CLI compatibility, EXE/resources/outer-folder resolution, ambiguous installs, deduplication, update, backup, saved data, checksum, rollback, downgrade.");return 0;
 }catch(Exception error){Console.Error.WriteLine(error.ToString());return 1;}finally{Directory.Delete(root,true);}}
}
